$ErrorActionPreference = "Stop"

$root = Split-Path -Parent $PSScriptRoot
$utf8 = New-Object System.Text.UTF8Encoding($false)

function Decode([string]$Value) {
    return [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($Value))
}

$sql = Decode ""

$migration85 = Join-Path $root "supabase\migrations\20260812202000_klyx_booking_groups_12_85.sql"
$migration96 = Join-Path $root "supabase\migrations\20260812223200_klyx_group_atomic_live_coverage_12_96.sql"
$financePath = Join-Path $root "app\api\provider\finance\route.ts"
$migrationPath = Join-Path $root "supabase\migrations\20260813102500_klyx_group_provider_accept_live_13_06.sql"

foreach ($path in @($migration85, $migration96, $financePath)) {
    if (-not (Test-Path -LiteralPath $path)) {
        throw "13.06 : fichier requis introuvable : $path"
    }
}

$sql85 = [System.IO.File]::ReadAllText($migration85)
$sql96 = [System.IO.File]::ReadAllText($migration96)
$finance = [System.IO.File]::ReadAllText($financePath)

if (-not $sql85.Contains("KLYX_BOOKING_GROUPS_12_85")) {
    throw "13.06 : booking groups 12.85 introuvables."
}

if (-not $sql85.Contains("klyx_provider_group_decision")) {
    throw "13.06 : RPC provider decision 12.85 introuvable."
}

if (-not $sql96.Contains("KLYX_GROUP_ATOMIC_LIVE_COVERAGE_12_96")) {
    throw "13.06 : garde atomique 12.96 introuvable."
}

if (-not $sql96.Contains("klyx_group_live_coverage_check")) {
    throw "13.06 : RPC live coverage 12.96 introuvable."
}

if (-not $finance.Contains("KLYX_GROUP_SCHEMA_RUNTIME_FINANCE_13_05C")) {
    throw "13.06 : KLYX 13.05c introuvable."
}

if (Test-Path -LiteralPath $migrationPath) {
    $existing = [System.IO.File]::ReadAllText($migrationPath)

    if (-not $existing.Contains("KLYX_GROUP_PROVIDER_ACCEPT_LIVE_GUARD_13_06")) {
        throw "13.06 : migration existante inattendue."
    }

    Write-Host "Migration 13.06 deja presente."
}
else {
    [System.IO.File]::WriteAllText($migrationPath, $sql, $utf8)
}

Write-Host ""
Write-Host "======================================"
Write-Host "KLYX 13.06 PREPARE"
Write-Host "======================================"
Write-Host "Provider accept : LIVE CHECK"
Write-Host "Couverture : N/N OBLIGATOIRE"
Write-Host "Planning : REVALIDE"
Write-Host "Conflits : REVALIDES"
Write-Host "Acceptation automatique : NON"
Write-Host "Booking automatique : NON"
Write-Host "Paiement automatique : NON"
Write-Host "======================================"
